const ACTIVE_STATUSES = ['ActiveM2M', 'ActiveTerm'];
const incomingCompanyId = $('Location lock check webhook').item.json.body.companyId || null;

const locations = $input.all().map((item) => item.json);

// The distinguishing rule from 05 Section 13, stated explicitly: a change originating from the
// SAME Company already holding an active Contract on this Location is Contract Amendment territory
// (a different workflow, contract-amendment-flow.workflow.json), NOT a Lock block. A Lock block is
// specifically an unrelated/different Company trying to generate a new Contract against a Location
// someone else already has active.
const conflicts = [];
const amendmentCandidates = [];

for (const loc of locations) {
  if (!ACTIVE_STATUSES.includes(loc.contractStatus)) continue;
  if (incomingCompanyId && loc.companyId === incomingCompanyId) {
    amendmentCandidates.push({ locationId: loc.id, contractStatus: loc.contractStatus });
  } else {
    conflicts.push({ locationId: loc.id, contractStatus: loc.contractStatus, heldByCompanyId: loc.companyId });
  }
}

return [{
  json: {
    blocked: conflicts.length > 0,
    conflicts,
    amendmentCandidates,
    reason: conflicts.length > 0
      ? `${conflicts.length} Location(s) already under an active Contract held by a different Company - routes to human review, does not auto-proceed.`
      : amendmentCandidates.length > 0
        ? `${amendmentCandidates.length} Location(s) already under an active Contract held by the SAME Company - this is Contract Amendment territory, not a new Contract. Route to contract-amendment-flow.workflow.json instead of creating a new one.`
        : 'No active Contract conflicts on any named Location.',
  },
}];
